fn print_usage() {
    println!("Honda OBD1 ECU (OKI MSM66207) Emulator & Testing CLI");
    println!("Usage:");
    println!(
        "  hondaecu-cli test <stock-p28-230.bin>                     Run stock P28 ROM/hardware sanity checks"
    );
    println!(
        "  hondaecu-cli datalog <rom.bin> [port]                     Start live serial datalogging TCP server (Port 38400)"
    );
    println!(
        "  hondaecu-cli replay <rom.bin> <log.csv|preset> [out.csv]  Replay CSV datalog / engine scenario through ECU"
    );
    println!(
        "  hondaecu-cli interactive <rom.bin>                        Launch interactive simulation REPL console"
    );
    println!(
        "  hondaecu-cli run <rom.bin> [instructions] [rpm]           Execute N instructions with approximate peripheral timing"
    );
    println!(
        "  hondaecu-cli disasm <rom.bin> [addr] [count]              Linearly disassemble ROM from an address"
    );
    println!();
    println!("Presets for 'replay':");
    println!("  dyno-pull, overrun-decel, overrun-downhill, accel-stomp, drag-pass,");
    println!("  electrical-load-idle, heat-soak-start, cold-start, launch-control-2step,");
    println!("  error-map-failure, error-ect-overheat, error-tps-short,");
    println!("  error-ckp-distributor-loss, error-vtec-oil-pressure-loss,");
    println!("  error-alt-low-voltage, error-o2-lean-stuck");
    println!();
    println!("Examples:");
    println!("  ./hondaecu-cli datalog P28-230.bin 38400");
    println!("  ./hondaecu-cli replay P28-230.bin dyno-pull");
    println!("  ./hondaecu-cli test P28-230.bin");
    println!("  ./hondaecu-cli interactive P28-230.bin");
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        print_usage();
        process::exit(1);
    }

    match args[1].as_str() {
        "datalog" | "server" => {
            let rom_path = args.get(2).map(|s| s.as_str()).unwrap_or("P28-230.bin");
            let port: u16 = args.get(3).and_then(|s| s.parse().ok()).unwrap_or(38400);

            if let Err(e) = DatalogServer::start_server(rom_path, port) {
                eprintln!("Error starting datalog server: {}", e);
                process::exit(1);
            }
        }

        "replay" | "play" | "log" => {
            let rom_path = args.get(2).map(|s| s.as_str()).unwrap_or("P28-230.bin");
            let log_source = args.get(3).map(|s| s.as_str()).unwrap_or("dyno-pull");
            let out_csv = args.get(4).map(|s| s.as_str());

            if let Err(e) = ReplayEngine::replay(rom_path, log_source, out_csv) {
                eprintln!("Error playing datalog: {}", e);
                process::exit(1);
            }
        }

        "test" => {
            let rom_path = args.get(2).map(|s| s.as_str()).unwrap_or("P28-230.bin");
            let results = EcuTestSuite::run_full_suite(rom_path);

            println!("\nTest Results Summary:");
            let mut total_passed = 0;
            for res in &results {
                let status = if res.passed {
                    total_passed += 1;
                    "[PASS]"
                } else {
                    "[FAIL]"
                };
                println!("  {:7} {} - {}", status, res.name, res.details);
            }
            println!(
                "\nTotal: {}/{} tests passed ({:.1}%)\n",
                total_passed,
                results.len(),
                (total_passed as f32 / results.len() as f32) * 100.0
            );

            if total_passed < results.len() {
                process::exit(1);
            }
        }

        "interactive" | "repl" => {
            let rom_path = args.get(2).map(|s| s.as_str()).unwrap_or("P28-230.bin");
            if let Err(e) = InteractiveShell::run(rom_path) {
                eprintln!("Interactive shell error: {}", e);
                process::exit(1);
            }
        }

        "run" | "sim" | "simulate" => {
            let rom_path = args.get(2).map(|s| s.as_str()).unwrap_or("P28-230.bin");
            let instruction_limit: u64 =
                args.get(3).and_then(|s| s.parse().ok()).unwrap_or(100_000);
            let target_rpm: f64 = args.get(4).and_then(|s| s.parse().ok()).unwrap_or(3000.0);

            println!(
                "Running ECU Emulation on '{}' for {} instructions at {:.0} RPM...",
                rom_path, instruction_limit, target_rpm
            );

            let mut bus = Bus::new();
            if let Err(e) = bus.load_rom_file(rom_path) {
                eprintln!("Failed to load ROM: {}", e);
                process::exit(1);
            }

            let mut cpu = Cpu::new();
            let mut engine = EngineState::new();

            cpu.pc = bus.read_code_u16(0x0000);
            if let Err(e) = ReplayEngine::boot_to_runtime(&mut cpu, &mut bus) {
                eprintln!("Failed to initialize ROM: {}", e);
                process::exit(1);
            }
            engine.rpm = target_rpm;

            let start = std::time::Instant::now();
            let start_instructions = cpu.instructions;
            let start_ticks = cpu.cycles;
            let mut interrupts_handled = 0;

            for _ in 0..instruction_limit {
                engine.sync_sensors_to_bus(&mut bus);
                let instruction_start = cpu.cycles;
                let instruction = Interpreter::step(&mut cpu, &mut bus);
                if cpu.halted {
                    eprintln!(
                        "ROM execution stopped at {:#06X}: {}",
                        instruction.pc, instruction.mnemonic
                    );
                    process::exit(1);
                }

                let elapsed_ticks = (cpu.cycles - instruction_start) as u32;
                let timer_irq = bus.tick_timers(elapsed_ticks);
                let dist_irq = engine.check_distributor_pulses(cpu.cycles, 12_000_000);

                if InterruptController::handle_pending_interrupts(
                    &mut cpu,
                    &mut bus,
                    timer_irq | dist_irq,
                ) {
                    interrupts_handled += 1;
                }
            }

            let duration = start.elapsed();
            let executed_instructions = cpu.instructions - start_instructions;
            let ips = (executed_instructions as f64) / duration.as_secs_f64();

            println!("Emulation Completed!");
            println!("  Approx. Core Ticks: {}", cpu.cycles - start_ticks);
            println!("  Instructions     : {}", executed_instructions);
            println!("  Execution Time   : {:.3?}", duration);
            println!(
                "  Host Throughput  : {:.2} instructions/sec ({:.2} M instr/s)",
                ips,
                ips / 1_000_000.0
            );
            println!("  Interrupts Handled: {}", interrupts_handled);
            println!(
                "  Last Measured Injector Pulse    : {} us",
                bus.injector_pulse_width_us
            );
            println!("  VTEC/IACV Telemetry             : unavailable (board mapping unverified)");
        }

        "disasm" => {
            let rom_path = args.get(2).map(|s| s.as_str()).unwrap_or("P28-230.bin");
            let start_addr: u16 = args
                .get(3)
                .and_then(|s| u16::from_str_radix(s.trim_start_matches("0x"), 16).ok())
                .unwrap_or(0x0000);
            let count: usize = args.get(4).and_then(|s| s.parse().ok()).unwrap_or(25);

            let mut bus = Bus::new();
            if let Err(e) = bus.load_rom_file(rom_path) {
                eprintln!("Failed to load ROM: {}", e);
                process::exit(1);
            }

            let mut cpu = Cpu::new();
            cpu.pc = start_addr;

            println!(
                "Disassembly of '{}' starting at {:#06X}:",
                rom_path, start_addr
            );
            for _ in 0..count {
                let ins = Interpreter::disassemble(&mut cpu, &bus);
                let hex = ins
                    .bytes
                    .iter()
                    .map(|b| format!("{:02X}", b))
                    .collect::<Vec<_>>()
                    .join(" ");
                println!("  {:#06X}: {:18} ; {}", ins.pc, ins.mnemonic, hex);
            }
        }

        _ => {
            print_usage();
            process::exit(1);
        }
    }
}
